/* Quadros urgentes e ajustes de referências. */
(function(root){'use strict';const P=root.PaisPPSPack;
const S=(id,name,url)=>P.sources[id]={name,url,checked:'2026-10-01'};
const R=(id,title,path)=>S(id,'RCH — '+title,'https://www.rch.org.au/kidsinfo/fact_sheets/'+path+'/');
const N=(id,title,path)=>S(id,'NHS — '+title,'https://www.nhs.uk/conditions/'+path+'/');
const arr=s=>s?s.split('~'):[];
const H=(id,refs,home,care,course,alarm,follow,options={})=>P.profiles[id]={refs:refs.split(','),home:arr(home),care:arr(care),course:arr(course),urgent:arr(alarm),follow:arr(follow),...options};
const U=(id,refs,action,care,why,alarm,detail='')=>H(id,refs,action,care,why,alarm,'A saída para casa e o retorno devem ser definidos pela equipe após avaliação e estabilização.'+(detail?'~'+detail:''),{urgency:true});
U('airway','epiglottitis,croup','Dificuldade respiratória importante ou ruído ao respirar em repouso precisa de atendimento imediato.','Mantenha a criança calma, na posição em que respira melhor. Não force deitar, examinar a garganta ou dar alimentos.','A equipe avaliará a passagem do ar e a necessidade de tratamento e observação.','Lábios arroxeados, exaustão, salivação com incapacidade de engolir ou redução da resposta.');
U('asthmaEmergency','asthma','Crise grave de asma é emergência; não aguarde melhora apenas com nebulização de soro.','Use o medicamento de resgate somente conforme o plano já prescrito, enquanto providencia atendimento.','Pode ser necessário oxigênio, medicação de resgate e monitorização.','Dificuldade para falar, tórax muito cansado, sonolência ou pouca entrada de ar.');
U('pleura','pneumonia','Suspeita de líquido ou pus ao redor do pulmão exige avaliação hospitalar.','Mantenha a criança acompanhada e confortável. Não adie o retorno para observar mais um dia de antibiótico.','A avaliação define a necessidade de exames, antibióticos e eventual drenagem.','Falta de ar, dor torácica importante, febre persistente com prostração ou arroxeamento.');
U('rehydration','diarrhea','O Plano B é reidratação com supervisão em serviço de saúde, não liberação automática para casa.','Se estiver alerta e conseguindo beber, ofereça pequenas quantidades de solução de reidratação orientada durante o deslocamento. Não force líquidos se estiver sonolenta ou engasgando.','A hidratação precisa ser reavaliada para decidir continuidade ou alta.','Pouco xixi, piora da sonolência, incapacidade de beber ou extremidades frias.');
U('shock','sepsis','Choque ou sinais de circulação comprometida exigem atendimento de emergência.','Mantenha a criança acompanhada e acione ajuda. Não force alimentos ou líquidos em criança sonolenta, com vômitos repetidos ou dificuldade para respirar.','O tratamento precisa de avaliação contínua da circulação e da respiração.','Desmaio, pele fria ou manchada, pouca resposta, falta de ar ou ausência de xixi.');
U('abdomen','appendix,intussusception','Suspeita de apendicite ou invaginação intestinal exige avaliação presencial imediata.','Não dê laxantes, não faça lavagem intestinal e não force alimentação. Leve exames e informe o horário da última refeição.','A equipe pode solicitar imagem e avaliação cirúrgica; melhorar por alguns minutos não exclui gravidade.','Dor intensa ou em crises com palidez, barriga distendida, vômito verde ou sangue nas fezes.');
U('dengueEmergency','dengue','Dengue com sinais de alarme precisa de atendimento imediato, mesmo se a febre já baixou.','Não use AAS ou anti-inflamatórios. Não adie atendimento para aguardar um exame.','A equipe avaliará hidratação, circulação, sangramentos e necessidade de internação.','Dor abdominal forte, vômitos persistentes, sangramento, sonolência ou extremidades frias.');
U('systemicInfection','sepsis,rickettsia,lepto','Esta infecção exige avaliação e tratamento rápidos; procure atendimento hoje, sem esperar piora.','Informe exposição a carrapatos, enchentes, animais, viagens e o dia de início dos sintomas. Não se automedique.','A investigação e o tratamento podem precisar começar antes da confirmação por exames.','Falta de ar, amarelão, sangramentos, confusão, manchas roxas ou pouca urina.');
U('sepsis','sepsis','Suspeita de sepse é emergência. Vá ao hospital agora; se a criança estiver grave, acione 192.','Não espere a febre baixar para procurar ajuda. Leve informação sobre medicamentos e doenças conhecidas.','A equipe investigará a infecção e a função dos órgãos e iniciará tratamento conforme a necessidade.','Respiração rápida, pele manchada, extremidades frias, dificuldade para acordar ou pouco xixi.');
U('seizureEmergency','seizure','Convulsão prolongada, repetida ou diferente do episódio simples exige atendimento imediato.','Afaste objetos, proteja a cabeça e marque o tempo. Não segure à força nem coloque nada na boca. Após cessar, se respirar, mantenha de lado e observe.','A equipe procurará a causa e decidirá observação e tratamento.','Crise com cinco minutos ou mais, crises sem recuperação, falta de ar ou dificuldade para acordar.');
U('brainEmergency','meningitis,head','Esta condição pode afetar o cérebro e precisa de atendimento de emergência.','Não deixe a criança sozinha. Em trauma, evite movimentação desnecessária; em convulsão, não coloque nada na boca.','Serão avaliados o nível de consciência, a respiração e a necessidade de exames e tratamento.','Sonolência crescente, confusão, rigidez de nuca com febre, fraqueza, convulsões ou vômitos repetidos.');
U('weakness','guillain','Fraqueza progressiva, dificuldade para andar, engolir ou respirar precisa de avaliação urgente.','Não force caminhadas ou ofereça comida se houver engasgos. Leve informação sobre a evolução da fraqueza.','A equipe avaliará nervos, força e respiração; algumas condições exigem monitorização hospitalar.','Fraqueza subindo pelas pernas, mudança na voz, engasgos ou falta de ar.');
U('anaphylaxis','anaphylaxis','Suspeita de anafilaxia é emergência. Acione 192.','Use imediatamente o autoinjetor de adrenalina se já estiver prescrito, seguindo o plano ensinado. Não deixe a criança levantar ou caminhar. Se falta de ar impedir deitar, mantenha posição confortável, sem ficar em pé.','Mesmo após melhora, é necessária avaliação e observação.','Falta de ar, rouquidão, inchaço da língua, desmaio ou reação rápida em mais de um sistema após exposição.');
U('renal','aki,nephrotic','Alteração aguda da função dos rins ou inchaço com xixi escuro precisa de avaliação presencial sem demora.','Não force água, não restrinja líquidos e não ofereça diuréticos ou anti-inflamatórios por conta própria. Leve resultados de exames.','O plano de líquidos e remédios será definido após avaliar pressão, urina, rins e sais do sangue.','Falta de ar, pouca urina, inchaço rápido, dor de cabeça intensa, vômitos ou sonolência.');
U('testicle','scrotal','Dor ou inchaço agudo no testículo exige pronto atendimento agora; torção precisa ser excluída rapidamente.','Não massageie nem tente destorcer. Não espere para ver se o analgésico resolve.','Será necessária avaliação presencial para distinguir torção de outras causas.','Dor súbita, vômitos, testículo em posição diferente ou piora do inchaço.');
U('arrest','firstaid','Se a criança não responde e não respira normalmente, ligue 192 em viva-voz e peça um desfibrilador, se houver.','Inicie reanimação conforme o treinamento recebido ou as instruções do atendente. Não perca tempo tentando classificar o ritmo cardíaco.','A equipe de emergência orientará e realizará o atendimento de reanimação.','Ausência de resposta e de respiração normal, incluindo apenas suspiros irregulares.');
U('heartEmergency','heart','Arritmia sintomática, suspeita de inflamação cardíaca ou cardiopatia descompensada precisa de avaliação urgente.','Mantenha repouso e evite esforço. Não dê doses extras de remédios cardíacos nem faça manobras não ensinadas.','A equipe poderá monitorizar coração, circulação e oxigenação.','Desmaio, dor no peito, falta de ar, palidez intensa, lábios arroxeados ou bebê suando e cansando nas mamadas.');
U('kawasaki','kawasaki','Suspeita de Kawasaki ou febre persistente com sinais de inflamação exige avaliação hospitalar sem demora.','Informe a duração da febre e alterações nos olhos, boca, pele e extremidades. Não comece AAS por conta própria.','A equipe avaliará inflamação e possível comprometimento do coração.','Prostração, falta de ar, dor no peito, desmaio ou sinais de circulação ruim.');
U('rheumatic','heart','Suspeita de febre reumática precisa de avaliação médica e investigação do coração.','Evite esforço até a avaliação. Leve registros de infecções de garganta e tratamentos recentes.','O acompanhamento definirá tratamento e prevenção de novos episódios.','Dor no peito, falta de ar, desmaio ou movimentos involuntários novos.','Após alta, não interrompa a prevenção prescrita por conta própria.');
U('fallot','heart','Crise de arroxeamento em criança com cardiopatia exige ajuda imediata.','Mantenha a criança calma. Siga apenas a posição de conforto e o plano de crise já ensinados pela cardiologia, enquanto aciona 192.','A equipe avaliará oxigenação e circulação.','Arroxeamento acentuado, respiração rápida, moleza ou desmaio.');
U('mastoid','mastoid','Suspeita de mastoidite precisa de avaliação hospitalar imediata.','Não esprema o inchaço atrás da orelha e não adie atendimento para esperar gotas ou antibiótico fazer efeito.','Podem ser necessários antibióticos por veia e avaliação do especialista.','Orelha projetada para frente, dor ou inchaço atrás dela, febre, dor de cabeça forte ou prostração.');
U('orbitalEmergency','orbital','Suspeita de infecção dentro da órbita é emergência e pode comprometer a visão.','Não pressione o olho e não use colírio por conta própria. Leve os medicamentos já usados.','A equipe avaliará visão, movimentos dos olhos e necessidade de exames e tratamento hospitalar.','Dor para mover o olho, visão reduzida, olho saltado, dor de cabeça forte ou sonolência.');
U('dka','dka','Cetoacidose diabética, mesmo chamada leve ou moderada, precisa de tratamento e observação hospitalares.','Leve o registro da glicemia e da insulina. Não faça doses extras fora do plano já prescrito e não atrase o atendimento.','A correção de glicose, líquidos e sais exige monitorização.','Respiração profunda, vômitos, dor abdominal, confusão ou sonolência.');
U('hypoglycemia','hypoglycemia','Hipoglicemia com sintomas precisa de correção e avaliação imediatas.','Se estiver acordada e engolindo com segurança, siga o plano de correção já ensinado. Se estiver sonolenta, convulsionando ou inconsciente, nada pela boca; acione 192 e use resgate somente se prescrito e treinado.','A equipe avaliará a causa e a possibilidade de nova queda da glicose.','Perda de consciência, convulsão, confusão ou incapacidade de engolir.');
U('electrolyteEmergency','electrolytes,hypernat,hypokal,hyperkal,aki','Distúrbios agudos ou sintomáticos dos sais do sangue precisam de avaliação presencial e correção monitorizada.','Não prepare soluções de sal, potássio ou cálcio em casa. Não aumente água nem mude remédios por conta própria. Leve os exames.','A velocidade e a forma de correção são determinadas por exames e monitorização.','Convulsão, confusão, fraqueza intensa, palpitações, desmaio ou falta de ar.');
U('adrenalEmergency','adrenal','Suspeita de crise adrenal é emergência. Acione ajuda e informe o diagnóstico de insuficiência adrenal.','Siga o plano de emergência já prescrito, inclusive resgate se treinado, sem atrasar a ida ao hospital. Não suspenda corticoide habitual abruptamente.','A equipe avaliará circulação, glicose e sais e fará a reposição necessária.','Vômitos que impedem a medicação, prostração intensa, desmaio ou confusão.');
U('jointInfection','septicJoint,osteomyelitis','Suspeita de infecção no osso ou articulação exige avaliação hospitalar urgente.','Não force o membro a apoiar ou se movimentar; mantenha posição confortável. Não atrase a avaliação para tentar tratar apenas a dor.','Serão avaliados exames, antibióticos e eventual necessidade de procedimento.','Febre com articulação quente e dolorosa, recusa de andar ou usar o braço, prostração.');
U('hipEmergency','sufe','Suspeita de deslizamento da cabeça do fêmur exige avaliação ortopédica urgente.','Não deixe apoiar peso na perna afetada e não tente alongar ou manipular o quadril.','A avaliação definirá o tratamento e como proteger a articulação.','Dor no quadril, virilha ou joelho com mancar ou impossibilidade de apoiar.');
U('poison','poison','Suspeita de ingestão excessiva de medicamento exige avaliação imediata, mesmo sem sintomas.','Leve a embalagem, o horário e a quantidade possivelmente ingerida. Não provoque vômito nem dê leite, comida, carvão ou neutralizantes por conta própria.','Algumas intoxicações demoram a causar sinais; não espere sintomas para buscar orientação.','Sonolência, vômitos repetidos, respiração anormal, convulsão ou desmaio.');
U('foreignBody','swallowed,poison','Suspeita de bateria tipo botão ou de vários ímãs engolidos exige pronto atendimento agora, mesmo sem sintomas.','Não provoque vômito, não dê laxantes e não espere o objeto sair nas fezes. Leve uma bateria ou embalagem igual, se houver, sem atrasar a saída.','A equipe verificará localização e necessidade de retirada rápida.','Dor, salivação, dificuldade para engolir, vômitos, sangue ou falta de ar.');
U('caustic','poison','Ingestão de produto corrosivo precisa de avaliação imediata.','Não provoque vômito nem tente neutralizar com vinagre, limão, bicarbonato, leite ou outro produto. Leve a embalagem.','Pode haver lesão interna mesmo sem queimadura evidente na boca.','Salivação, dor para engolir, vômitos, dor torácica ou dificuldade respiratória.');
U('venom','venom','Picada de escorpião ou suspeita de cobra venenosa em criança exige atendimento imediato.','Lave com água e sabão e mantenha repouso. Não faça torniquete, cortes ou sucção e não coloque substâncias na ferida. Não tente capturar o animal.','A equipe avaliará a necessidade de soro e monitorização.','Vômitos, suor intenso, sonolência, dificuldade respiratória, sangramento ou dor e inchaço progressivos.');
U('neonatal','neonate,sepsis,jaundice','Recém-nascido com alteração respiratória, temperatura baixa ou sinais de infecção precisa de atendimento imediato.','Mantenha aquecido com roupas ou manta seca, sem aquecedor direto, bolsa quente ou banho quente. Não force mamada se estiver muito sonolento ou com dificuldade para respirar.','A equipe avaliará respiração, temperatura, alimentação e possíveis causas que exigem observação.','Pausas respiratórias, gemência, arroxeamento, dificuldade para acordar ou mamar.');
U('jaundiceSevere','jaundice','Icterícia por incompatibilidade sanguínea com indicação de tratamento intensivo exige acompanhamento hospitalar.','Não substitua o tratamento por banho de sol e não atrase exames ou retorno. Leve os registros da maternidade.','A equipe acompanhará bilirrubina, anemia e necessidade de tratamento específico.','Bebê muito sonolento, mamando mal, choro agudo, rigidez, moleza intensa ou piora rápida do amarelão.');

N('outerEar','Infecções do ouvido','ear-infections');R('osteomyelitis','Osteomielite','Osteomyelitis');
R('appendix','Apendicite','Appendicitis');R('sufe','Epifisiólise','Slipped_upper_femoral_epiphysis_SUFE');
S('intussusception','RCH — Invaginação intestinal','https://www.rch.org.au/clinicalguide/guideline_index/Intussusception/');
S('scrotal','RCH — Dor testicular aguda','https://www.rch.org.au/clinicalguide/guideline_index/Acute_Scrotal_Pain_or_Swelling/');
S('guillain','Ministério da Saúde — Guillain-Barré','https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/g/sindrome-de-guillain-barre');
S('hypertension','RCH — Hipertensão pediátrica','https://www.rch.org.au/clinicalguide/guideline_index/hypertension/');
S('hypernat','RCH — Hipernatremia','https://www.rch.org.au/clinicalguide/guideline_index/Hypernatraemia/');
S('hypokal','RCH — Hipocalemia','https://www.rch.org.au/clinicalguide/guideline_index/hypokalaemia/');
S('hyperkal','RCH — Hipercalemia','https://www.rch.org.au/clinicalguide/guideline_index/Hyperkalaemia/');
S('neonate','RCH — Recém-nascido e lactente com sinais de gravidade','https://www.rch.org.au/clinicalguide/guideline_index/Recognition_of_the_seriously_unwell_neonate_and_young_infant/');
P.profiles.infectedVaricella={...P.profiles.cellulitis,refs:['cellulitis','varicella'],care:[...P.profiles.cellulitis.care,'Não use AAS. Evite ibuprofeno na varicela, salvo orientação médica específica. Mantenha as lesões limpas e as unhas curtas.'],follow:[...P.profiles.cellulitis.follow,'Evite contato com gestantes, recém-nascidos e pessoas com baixa imunidade até o fim da fase contagiosa.']};
U('hypertension','hypertension','Pressão muito elevada com sintomas exige avaliação presencial imediata.','Mantenha repouso e leve registros das medidas e medicamentos. Não dê doses extras nem tente baixar a pressão rapidamente por conta própria.','A equipe confirmará a pressão com técnica adequada e verificará se há órgãos comprometidos.','Dor de cabeça intensa, visão alterada, vômitos, falta de ar, dor no peito, confusão ou convulsão.');
U('paraphimosis','penis','Pele presa atrás da ponta do pênis com inchaço caracteriza uma urgência: procure atendimento agora.','Não force a pele nem tente cortar ou manipular com instrumentos.','A equipe avaliará a circulação e fará a redução ou o tratamento necessário.','Dor intensa, mudança de cor ou dificuldade para urinar.');
U('dacryocystitis','tear,orbital','Inchaço doloroso e avermelhado junto ao canto interno do olho precisa de atendimento imediato, especialmente em bebês.','Não esprema nem massageie o inchaço infectado; não use colírios por conta própria.','Pode ser necessário antibiótico e avaliação especializada.','Febre, prostração, vermelhidão que aumenta, dor para mover o olho ou visão alterada.');
P.variants=[[79,'Parafimose aguda','Rins e trato urinário','paraphimosis','parafimose'],[103,'Dacriocistite aguda','Ouvidos e olhos','dacryocystitis','dacriocistite']];
root.PaisPPSPack=P;if(typeof module==='object'&&module.exports)module.exports=P;
})(typeof window!=='undefined'?window:globalThis);
